from __future__ import annotations

import csv
import json
import warnings
from collections.abc import Iterable
from dataclasses import replace
from pathlib import Path
from typing import Any, TypedDict

from ..contracts.types import ChatMessage
from ..utils.core import serialize_value
from .types import DatasetRecord, DatasetSource, TaskExample

try:
    from bson import decode_file_iter
except Exception:
    decode_file_iter = None  # type: ignore[assignment]


def load_records(path: str | Path) -> list[dict[str, Any]]:
    input_path = Path(path)
    if not input_path.is_file():
        raise FileNotFoundError(f"Input dataset not found: {input_path}")

    suffix = input_path.suffix.lower()
    if suffix == ".jsonl":
        return _read_jsonl_records(input_path)
    if suffix == ".json":
        return _read_json_records(input_path)
    if suffix == ".csv":
        return _read_csv_records(input_path)
    if suffix == ".txt":
        return _read_txt_records(input_path)
    if suffix == ".bson":
        return _read_bson_records(input_path)
    raise ValueError(f"Unsupported dataset extension: {input_path.suffix}")


def load_task_examples(source: DatasetSource) -> list[TaskExample]:
    if isinstance(source, (str, Path)):
        examples = [task_example_from_record(record) for record in load_records(source)]
    else:
        examples = [task_example_from_source_item(item) for item in source]
    loaded_examples = [
        example if example.id else replace(example, id=stable_example_id(index))
        for index, example in enumerate(examples)
    ]
    _ensure_unique_example_ids(loaded_examples)
    return loaded_examples


def _ensure_unique_example_ids(examples: list[TaskExample]) -> None:
    positions_by_id: dict[str, int] = {}
    for index, example in enumerate(examples):
        if not example.id:
            continue
        first_index = positions_by_id.get(example.id)
        if first_index is not None:
            raise ValueError(
                f"Duplicate dataset example id {example.id!r} at positions "
                f"{first_index} and {index}; example ids must be unique. "
                "Positional fallback ids use the example_NNNNNN format, so "
                "choose explicit ids that do not collide with generated ids."
            )
        positions_by_id[example.id] = index


def stable_example_id(index: int) -> str:
    """Deterministic positional fallback id for records without an explicit id.

    Local SDK loading and remote workers derive the SAME id for the same source
    position, so example selection by id behaves identically in both places.
    """
    return f"example_{index:06d}"


def task_example_from_source_item(
    value: TaskExample | DatasetRecord,
) -> TaskExample:
    if isinstance(value, TaskExample):
        return value
    return task_example_from_record(value)


class NormalizedRecord(TypedDict):
    id: str | None
    input: str
    metadata: dict[str, Any]


def task_example_from_record(record: DatasetRecord) -> TaskExample:
    normalized = normalize_record(record)
    return TaskExample(
        record=record,
        input=normalized["input"],
        id=normalized["id"],
        metadata=normalized["metadata"],
        output=infer_output(record),
    )


def normalize_record(record: dict[str, Any]) -> NormalizedRecord:
    """Derive the canonical ``id``/``input``/``metadata`` view of a record.

    This is only the typed view used to populate ``TaskExample.input``/``id``/
    ``metadata``; it does not itself drop anything, since the full original
    record is kept verbatim on ``TaskExample.record`` and reaches remote
    training workers intact. Individual downstream consumers may still project a
    record onto a fixed column set -- e.g. eval-result uploads
    (``_data_object``) serialize only ``input``/``output``/``id``/``metadata``/
    ``image_url`` plus generation data -- so anything such a consumer must
    persist belongs under ``metadata``.
    """
    if "input" not in record or record.get("input") is None:
        raise ValueError("Each record must contain input")

    metadata = record.get("metadata")
    return {
        "id": _record_id(record),
        "input": serialize_value(record["input"]),
        "metadata": metadata if isinstance(metadata, dict) else {},
    }


def _record_id(record: dict[str, Any]) -> str | None:
    for key in ("id", "_id"):
        if key not in record or record[key] is None:
            continue
        normalized = str(record[key]).strip()
        if normalized:
            return normalized
    return None


def warn_missing_think_tags(examples: Iterable[TaskExample]) -> list[str]:
    """Warn about SFT gold outputs missing a literal ``<think>...</think>`` block.

    Thinking-model SFT workers require the gold completion to literally contain
    ``<think>...</think>``; this surfaces the problem locally before submitting a
    run. Expects LOADED examples (``load_dataset`` / ``load_task_examples``),
    which always carry ids. Returns the ids of the offending examples.
    """
    missing: list[str] = []
    for example in examples:
        if example.output is None:
            continue
        if not example.id:
            raise ValueError(
                "warn_missing_think_tags requires loaded examples with ids; "
                "load them via load_dataset or load_task_examples first"
            )
        text = _assistant_output_text(example.output)
        if "<think>" in text and "</think>" in text:
            continue
        missing.append(example.id)
    if missing:
        preview = ", ".join(missing[:5])
        warnings.warn(
            f"{len(missing)} SFT gold output(s) lack a literal <think>...</think> "
            f"block (e.g. {preview}); thinking-model SFT workers expect it to be "
            "present in the target completion.",
            UserWarning,
            stacklevel=2,
        )
    return missing


def _assistant_output_text(output: object) -> str:
    return "\n".join(
        content
        for message in target_messages(output)
        if message.get("role") == "assistant"
        and isinstance(content := message.get("content"), str)
    )


def target_messages(expected_output: object) -> list[ChatMessage]:
    """The gold COMPLETION messages a labeled record's ``output`` denotes — the single thing a
    trainer appends after the prompt for SFT.

    - A MULTI-TURN gold trajectory authored as ``output = {"messages": [...]}`` (canonical) or a
      bare list of chat messages -> the parsed message list (assistant turns + tool calls + tool
      results + replies). ``len(...) > 1`` means it is genuinely multi-turn.
    - Any scalar ``output`` -> a single assistant turn whose content is that value (single-turn SFT).

    Messages support BOTH the text tool protocol (``<tool_call>`` / ``<tool_result>`` in string
    content) and OpenAI-native tool calling (assistant ``tool_calls`` + ``tool``-role result
    messages), preserved verbatim.
    """
    if isinstance(expected_output, dict) and set(expected_output) == {"messages"}:
        return _parse_chat_messages(expected_output["messages"])
    if (
        isinstance(expected_output, list)
        and expected_output
        and all(
            isinstance(m, dict) and isinstance(m.get("role"), str)
            for m in expected_output
        )
    ):
        return _parse_chat_messages(expected_output)
    return [
        {
            "role": "assistant",
            "content": ""
            if expected_output is None
            else serialize_value(expected_output),
        }
    ]


def _parse_chat_messages(value: object) -> list[ChatMessage]:
    if not isinstance(value, list):
        raise ValueError("Expected output messages must be a list of chat messages")
    if not value:
        raise ValueError("Expected output messages must contain at least one message")
    messages: list[ChatMessage] = []
    for index, item in enumerate(value):
        if not isinstance(item, dict):
            raise ValueError(
                f"Expected output messages[{index}] must be a chat message object"
            )
        role = item.get("role")
        if not isinstance(role, str) or not role.strip():
            raise ValueError(
                f"Expected output messages[{index}].role must be a non-empty string"
            )
        content = item.get("content")
        has_tool_calls = bool(item.get("tool_calls"))
        # Content must be a string, or null when the assistant message carries tool_calls (native
        # tool calling); anything else (e.g. an int) is invalid. The whole message dict is then
        # preserved so tool_calls / tool_call_id / name / etc. round-trip into the SFT example.
        if content is not None and not isinstance(content, str):
            raise ValueError(
                f"Expected output messages[{index}].content must be a string or null"
            )
        if content is None and not has_tool_calls:
            raise ValueError(
                f"Expected output messages[{index}].content must be a string "
                "(or null only with tool_calls)"
            )
        message: ChatMessage = dict(item)  # type: ignore[assignment]
        message["role"] = role.strip()
        messages.append(message)
    return messages


def infer_output(record: dict[str, Any]) -> Any:
    if "output" in record and record.get("output") is not None:
        return record.get("output")
    return None


def _read_jsonl_records(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    with path.open("r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, start=1):
            stripped = line.strip()
            if not stripped:
                continue
            parsed = json.loads(stripped)
            if isinstance(parsed, str):
                parsed = {"input": parsed}
            if not isinstance(parsed, dict):
                raise ValueError(
                    f"Expected JSON object on line {line_number} of {path}"
                )
            records.append(parsed)
    return records


def _read_json_records(path: Path) -> list[dict[str, Any]]:
    parsed = json.loads(path.read_text(encoding="utf-8"))
    if isinstance(parsed, dict) and isinstance(parsed.get("data"), list):
        parsed = parsed["data"]
    if not isinstance(parsed, list):
        raise ValueError(f"Expected a JSON array of objects in {path}")
    records: list[dict[str, Any]] = []
    for item in parsed:
        if isinstance(item, str):
            item = {"input": item}
        if not isinstance(item, dict):
            raise ValueError(f"Expected JSON object items in {path}")
        records.append(item)
    return records


def _read_csv_records(path: Path) -> list[dict[str, Any]]:
    with path.open("r", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle)
        return [dict(row) for row in reader]


def _read_txt_records(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for index, line in enumerate(path.read_text(encoding="utf-8").splitlines()):
        stripped = line.strip()
        if stripped:
            records.append({"id": f"input_{index:06d}", "input": stripped})
    return records


def _read_bson_records(path: Path) -> list[dict[str, Any]]:
    if decode_file_iter is None:
        raise RuntimeError("Install bson or pymongo to read BSON prompt sources")
    with path.open("rb") as handle:
        return [dict(raw) for raw in decode_file_iter(handle)]
